1	// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
2	// ④ 接收后台指令自动切店(轮巡用)。
3	(function () {
4	  const LOG = (...a) => { try { console.log('[TemuMon]', ...a); } catch (e) {} };
5	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
6	  console.log('%c[TemuMon] content.js 已加载 —— 限流明细版 v2', 'color:#16a34a;font-weight:bold');
7	
8	  // 注入 MAIN world hook
9	  try {
10	    const s = document.createElement('script');
11	    s.src = chrome.runtime.getURL('inject.js');
12	    s.onload = () => s.remove();
13	    (document.head || document.documentElement).appendChild(s);
14	  } catch (e) { /* ignore */ }
15	
16	  // ---------- 读当前店铺名（右上角英文店名） ----------
17	  function findStoreNameEl() {
18	    const W = window.innerWidth;
19	    let best = null;
20	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
21	      const t = (el.textContent || '').trim();
22	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
23	      if (t.length < 2 || t.length > 30) continue;
24	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
25	      // 排除纯大写+数字的货号/SKU（如 JMCATSZJ4）——真实店名都含小写字母
26	      if (/^[A-Z0-9]+$/.test(t)) continue;
27	      if (el.children.length > 2) continue;
28	      const r = el.getBoundingClientRect();
29	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
30	      if (r.left < W * 0.5) continue;
31	      if (!best || r.left > best.left) best = { el, left: r.left };
32	    }
33	    return best ? best.el : null;
34	  }
35	  function readStoreName() { const el = findStoreNameEl(); return el ? (el.textContent || '').trim() : null; }
36	
37	  // ---------- 转发接口响应 ----------
38	  window.addEventListener('message', (e) => {
39	    if (e.source !== window) return;
40	    const d = e.data;
41	    if (!d || d.__temuMon !== true) return;
42	    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
43	  });
44	
45	  // ---------- 读流量异常 ----------
46	  // ①「商品流量待关注」是常驻的快速筛选 chip，实测 DOM（勿凭空改）：
47	  //     <div class="use-quick-field_tsx_card__HASH"><span>商品流量待关注</span>
48	  //       <span class="use-quick-field_tsx_countDistance__HASH">4</span></div>
49	  //   计数在独立的 countDistance span 里（chip 常驻，N=0 也在，只有 N 变大才是真异常）。
50	  // ②「商品流量近期有下降」不是 chip，是逐行红色徽标（见 countDeclineBadges）。
51	  // 关键坑：行内徽标「商品流量待关注 ›」嵌在价格 TD 里 → 价格单元格文本也含该标签。
52	  //   旧的"全页捞文本+最短优先"靠排序巧合才没读到价格数字；这里改为直接锚定 chip 容器。
53	  function readChipCount(all, label) {
54	    const re = new RegExp(label);
55	    // 精确路径：定位快速筛选 chip 容器（class 前缀 use-quick-field_tsx_card__ 稳定，
56	    // hash 后缀随构建变，用 *= 匹配前缀；card__ 带双下划线以免误匹配 cardBlock__）。
57	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
58	      if (!re.test(card.textContent || '')) continue;
59	      const cnt = card.querySelector('[class*="countDistance"]');
60	      if (cnt && /\d/.test(cnt.textContent || '')) {
61	        return Number((cnt.textContent || '').replace(/[^\d]/g, ''));
62	      }
63	      const m = (card.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
64	      if (m) return Number(m[1].replace(/,/g, ''));
65	    }
66	    // 兜底：chip class 若被改名，退回旧的全页文本匹配（最短优先 + 就近数字）
67	    const labels = all
68	      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
69	      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
70	    for (const el of labels) {
71	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
72	        if (!cand) continue;
73	        const m = (cand.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
74	        if (m) return Number(m[1].replace(/,/g, ''));
75	      }
76	      let sib = el.nextElementSibling;
77	      for (let i = 0; i < 3 && sib; i++, sib = sib.nextElementSibling) {
78	        const st = (sib.textContent || '').trim();
79	        if (/^[\d,]+$/.test(st)) return Number(st.replace(/,/g, ''));
80	      }
81	    }
82	    return null; // 读不到 → 未知（不当作 0，也不当作"有"）
83	  }
84	  // 「商品流量近期有下降」不是带计数的筛选 chip，而是逐行的红色徽标（列「商品优化事项」下）。
85	  // 因此按"当前页可见的行内徽标个数"来统计。注意：只覆盖当前页（默认 20 条/页），
86	  // 下降商品若在其它页则数不到——被动读数的固有限制，要精确总数得点筛选（主动模式）。
87	  function countDeclineBadges(all) {
88	    let n = 0;
89	    for (const e of all) {
90	      const t = (e.textContent || '').trim();
91	      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
92	      // 只数最内层节点，避免父容器重复计数
93	      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
94	      const r = e.getBoundingClientRect();
95	      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
96	    }
97	    return n;
98	  }
99	  // 扫描当前页商品行：按「SPU ID(=productId)」边界把行分组成商品，
100	  // 识别哪些商品带「商品流量待关注 / 商品流量近期有下降」徽标，取 productId + 商品名 + SKC。
101	  // 局限：只覆盖当前页(默认 20 条/页)，跨页的限流/下降商品扫不到——被动读的固有限制
102	  //（chip 计数 trafficWatch 才是全量总数；这里只为「点名 + 给编辑链接」）。
103	  function scanProducts() {
104	    const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
105	    const products = [];
106	    let cur = null;
107	    for (const tr of rows) {
108	      const t = tr.textContent || '';
109	      const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/); // DOM「SPU ID」= API/编辑页的 productId
110	      if (spu) {
111	        // 商品名只在「商品信息」那一格取（含 SPU ID 的 td），排除「标签：值」属性行，取最长一段。
112	        // （曾扫整行 → 第 3 条抓成隔壁「商品属性」列的「主体材质：铝合金」，故限定到该 td。）
113	        const infoTd = [...tr.querySelectorAll('td')].find((td) => /SPU\s*ID/.test(td.textContent || '')) || tr;
114	        const name = [...infoTd.querySelectorAll('*')].map((e) => (e.textContent || '').trim())
115	          .filter((x) => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
116	          .sort((a, b) => b.length - a.length)[0] || '';
117	        cur = { productId: spu[1], skc: (t.match(/SKC\s*ID[:：]\s*(\d+)/) || [])[1] || '', name: name, watch: false, decline: false };
118	        products.push(cur);
119	      }
120	      if (cur) {
121	        if (/商品流量待关注/.test(t)) cur.watch = true;
122	        if (/商品流量近期有下降/.test(t)) cur.decline = true;
123	      }
124	    }
125	    return products;
126	  }
127	  function readTraffic() {
128	    const all = [...document.querySelectorAll('*')];
129	    return {
130	      watch: readChipCount(all, '商品流量待关注'),
131	      decline: countDeclineBadges(all),
132	    };
133	  }
134	  const pickItem = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
135	  // 常驻轮询：每 2s 读一次 chip 计数 + 扫一次商品明细，但**只在结果变化时上报**
136	  //（靠 dedupe 避免刷爆后台）。这样用户后点「商品流量待关注」筛选/翻页时，
137	  // 明细也会在 2s 内自动刷新——旧版只在加载后 40s 内扫、之后点筛选就不扫了。
138	  let tries = 0;
139	  let lastKey = '';
140	  setInterval(() => {
141	    tries++;
142	    // 商品表格是否已渲染出行——徽标在行里，必须等行出来再扫，否则会在徽标出现前就读成空
143	    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
144	    const { watch, decline } = readTraffic();
145	    const msg = { type: 'chipStats', store: readStoreName() };
146	    if (watch != null) msg.trafficWatch = watch;
147	    let watchItems = [];
148	    let declineItems = [];
149	    if (gridReady) {
150	      const products = scanProducts();
151	      watchItems = products.filter((p) => p.watch).map(pickItem);
152	      declineItems = products.filter((p) => p.decline).map(pickItem);
153	      msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
154	      msg.watchItems = watchItems;
155	      msg.declineItems = declineItems;
156	    }
157	    // 有 count 时等网格就绪再发（尽量带上明细）；网格长时间卡「加载中」(tries>8≈16s)时 count-only 兜底
158	    const readyOrTimedOut = gridReady || tries > 8;
159	    if (!((msg.trafficWatch != null && readyOrTimedOut) || 'trafficDecline' in msg)) return;
160	    // 结果没变化就不重发；变化了（如刚点了筛选、切了店）才上报
161	    const key = JSON.stringify([msg.store, msg.trafficWatch, msg.trafficDecline,
162	      watchItems.map((i) => i.productId), declineItems.map((i) => i.productId)]);
163	    if (key === lastKey) return;
164	    lastKey = key;
165	    try { chrome.runtime.sendMessage(msg); } catch (e) {}
166	  }, 2000);
167	
168	  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
169	  async function waitFor(fn, timeout, step) {
170	    const t0 = Date.now();
171	    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
172	  }
173	  function textEls(re, maxLen) {
174	    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
175	  }
176	  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
177	  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
178	  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
179	  function realClick(el) {
180	    if (!el) return false;
181	    const opts = { bubbles: true, cancelable: true, view: window };
182	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
183	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
184	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
185	    }
186	    try { el.click(); } catch (e) {}
187	    return true;
188	  }
189	  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
190	  function closeModal() {
191	    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
192	    if (x) { realClick(x); return; }
193	    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
194	  }
195	
196	  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
197	  function domSkel(el, maxLen) {
198	    if (!el) return 'null';
199	    let h = (el.outerHTML || '');
200	    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
201	    return h.slice(0, maxLen || 2200);
202	  }
203	
204	  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }
205	
206	  async function openStoreModal(diag) {
207	    diag = diag || [];
208	    if (modalOpen()) { diag.push('弹窗已开'); return true; }
209	    const nameEl = findStoreNameEl();
210	    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
211	    if (nameEl) {
212	      // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
213	      const r = nameEl.getBoundingClientRect();
214	      realClick(clickableAncestor(nameEl));
215	      const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
216	      if (el && el !== nameEl) realClick(el);
217	    }
218	    // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
219	    const sw = await waitFor(() => {
220	      const cands = textEls(/^切换$/, 6).filter(visible);
221	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
222	    }, 3500);
223	    diag.push('下拉切换按钮=' + !!sw);
224	    if (sw) realClick(sw);
225	    const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
226	    diag.push('弹窗打开=' + ok);
227	    if (!ok) {
228	      const cands = textEls(/切换/, 8).map((e) => {
229	        const b = e.getBoundingClientRect();
230	        return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
231	      });
232	      diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
233	      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
234	    }
235	    return ok;
236	  }
237	
238	  async function listStores() {
239	    if (!(await openStoreModal())) return [];
240	    await sleep(500);
241	    // 每个店铺行都带“半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文
242	    const tags = textEls(/托管/, 6).filter(visible);
243	    const names = [];
244	    for (const tag of tags) {
245	      let row = tag.parentElement;
246	      for (let i = 0; i < 4 && row; i++) {
247	        const en = [...row.querySelectorAll('span,div,p,a')]
248	          .map((e) => (e.textContent || '').trim())
249	          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
250	        if (en) { names.push(en); break; }
251	        row = row.parentElement;
252	      }
253	    }
254	    closeModal();
255	    const uniq = [...new Set(names)];
256	    LOG('listStores =>', uniq);
257	    return uniq;
258	  }
259	
260	  async function switchTo(target) {
261	    const diag = [];
262	    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
263	    await sleep(300);
264	    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
265	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
266	    const row = innermost(rows);
267	    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
268	    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
269	    if (!btn) {
270	      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
271	      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
272	    }
273	    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
274	    LOG('switchTo click', target);
275	    realClick(btn); // 触发切店（SPA 更新或整页重载）
276	    return { ok: true, msg: '已点击切换到 ' + target };
277	  }
278	
279	  // ---------- 主动捞「商品流量待关注」明细（发现异常时调，点筛选→扫→重置） ----------
280	  // 读列表底部「共有 N 条」（筛选生效后该数=待关注总数）
281	  function readTotalCount() {
282	    const el = [...document.querySelectorAll('*')].find(
283	      (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
284	    );
285	    if (!el) return null;
286	    const m = (el.textContent || '').match(/共有\s*([\d,]+)\s*条/);
287	    return m ? Number(m[1].replace(/,/g, '')) : null;
288	  }
289	  // 定位「商品流量待关注」快速筛选 chip 容器（与 readChipCount 同一稳定 class 前缀）
290	  function findWatchChip() {
291	    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
292	      if (/商品流量待关注/.test(card.textContent || '')) return card;
293	    }
294	    return null;
295	  }
296	  // 点「重置」清掉快速筛选，恢复用户视图
297	  function clickReset() {
298	    const btn = textEls(/^重置$/, 6).filter(visible)[0];
299	    if (btn) realClick(clickableAncestor(btn));
300	  }
301	  // 点开「商品流量待关注」筛选 → 扫出这几条商品(productId+name+skc) → 重置。
302	  // 筛选生效后网格里每行都是待关注商品，故取全部行（不再依赖行内徽标）。
303	  // 只覆盖筛选后的当前页(默认 20 条)，>20 条的溢出由 total 提示行说明。
304	  async function scanWatchList() {
305	    const chip = findWatchChip();
306	    if (!chip) return { store: readStoreName(), items: [], applied: false, msg: '未找到待关注筛选 chip' };
307	    const before = readTotalCount();
308	    realClick(clickableAncestor(chip));
309	    // 等列表真正刷新：底部「共有 N 条」的数值发生变化（通常变小）才算筛选生效
310	    await waitFor(() => {
311	      const t = readTotalCount();
312	      return (t != null && before != null && t !== before) ? t : null;
313	    }, 8000, 300);
314	    await sleep(1200); // 等筛选后的网格稳定渲染
315	    const after = readTotalCount();
316	    // 仅当确实生效（数值变化且不大于原总数）才采纳，绝不把未筛选的整页当成待关注
317	    const applied = after != null && before != null && after !== before && after <= before;
318	    let items = [];
319	    if (applied) items = scanProducts().map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
320	    clickReset();
321	    await sleep(800);
322	    return { store: readStoreName(), items: items, total: after, applied: applied };
323	  }
324	
325	  // 扫「在售中」商品清单：点在售 tab → 等在售网格 → scanProducts 取 productId+name+skc。
326	  // 用于 background diff 出"上轮在售、这轮不在"的下架商品。仅轮巡(空闲)时调，扫完点回「全部」。
327	  async function scanOnSaleList() {
328	    const findTab = (re) => {
329	      const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
330	      return labels.find((e) => re.test((e.textContent || '').trim())) || textEls(re, 14).filter(visible)[0] || null;
331	    };
332	    const onSaleTab = findTab(/^在售中/);
333	    if (onSaleTab) realClick(clickableAncestor(onSaleTab));
