335	    await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
336	    const products = scanProducts();
337	    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
338	    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
339	    const allTab = findTab(/^全部/);
340	    if (allTab) realClick(clickableAncestor(allTab));
341	    return { store: readStoreName(), items: items };
342	  }
