// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
// ④ 接收后台指令自动切店(轮巡用)。
(function () {
  const LOG = (...a) => { try { console.log('[TemuMon]', ...a); } catch (e) {} };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  console.log('%c[TemuMon] content.js 已加载 —— 限流明细版 v2', 'color:#16a34a;font-weight:bold');

  // 注入 MAIN world hook
  try {
    const s = document.createElement('script');
    s.src = chrome.runtime.getURL('inject.js');
    s.onload = () => s.remove();
    (document.head || document.documentElement).appendChild(s);
  } catch (e) { /* ignore */ }

  // ---------- 读当前店铺名（右上角英文店名） ----------
  function findStoreNameEl() {
    const W = window.innerWidth;
    let best = null;
    for (const el of document.querySelectorAll('span,a,div,button,p')) {
      const t = (el.textContent || '').trim();
      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
      if (t.length < 2 || t.length > 30) continue;
      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
      // 排除纯大写+数字的货号/SKU（如 JMCATSZJ4）——真实店名都含小写字母
      if (/^[A-Z0-9]+$/.test(t)) continue;
      if (el.children.length > 2) continue;
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
      if (r.left < W * 0.5) continue;
      if (!best || r.left > best.left) best = { el, left: r.left };
    }
    return best ? best.el : null;
  }
  function readStoreName() { const el = findStoreNameEl(); return el ? (el.textContent || '').trim() : null; }

  // ---------- 转发接口响应 ----------
  window.addEventListener('message', (e) => {
    if (e.source !== window) return;
    const d = e.data;
    if (!d || d.__temuMon !== true) return;
    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
  });

  // ---------- 读流量异常 ----------
  // ①「商品流量待关注」是常驻的快速筛选 chip，实测 DOM（勿凭空改）：
  //     <div class="use-quick-field_tsx_card__HASH"><span>商品流量待关注</span>
  //       <span class="use-quick-field_tsx_countDistance__HASH">4</span></div>
  //   计数在独立的 countDistance span 里（chip 常驻，N=0 也在，只有 N 变大才是真异常）。
  // ②「商品流量近期有下降」不是 chip，是逐行红色徽标（见 countDeclineBadges）。
  // 关键坑：行内徽标「商品流量待关注 ›」嵌在价格 TD 里 → 价格单元格文本也含该标签。
  //   旧的"全页捞文本+最短优先"靠排序巧合才没读到价格数字；这里改为直接锚定 chip 容器。
  function readChipCount(all, label) {
    const re = new RegExp(label);
    // 精确路径：定位快速筛选 chip 容器（class 前缀 use-quick-field_tsx_card__ 稳定，
    // hash 后缀随构建变，用 *= 匹配前缀；card__ 带双下划线以免误匹配 cardBlock__）。
    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
      if (!re.test(card.textContent || '')) continue;
      const cnt = card.querySelector('[class*="countDistance"]');
      if (cnt && /\d/.test(cnt.textContent || '')) {
        return Number((cnt.textContent || '').replace(/[^\d]/g, ''));
      }
      const m = (card.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
      if (m) return Number(m[1].replace(/,/g, ''));
    }
    // 兜底：chip class 若被改名，退回旧的全页文本匹配（最短优先 + 就近数字）
    const labels = all
      .filter((e) => re.test(e.textContent || '') && (e.textContent || '').trim().length < 24)
      .sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
    for (const el of labels) {
      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
        if (!cand) continue;
        const m = (cand.textContent || '').match(new RegExp(label + '[^\\d]{0,3}([\\d,]+)'));
        if (m) return Number(m[1].replace(/,/g, ''));
      }
      let sib = el.nextElementSibling;
      for (let i = 0; i < 3 && sib; i++, sib = sib.nextElementSibling) {
        const st = (sib.textContent || '').trim();
        if (/^[\d,]+$/.test(st)) return Number(st.replace(/,/g, ''));
      }
    }
    return null; // 读不到 → 未知（不当作 0，也不当作"有"）
  }
  // 「商品流量近期有下降」不是带计数的筛选 chip，而是逐行的红色徽标（列「商品优化事项」下）。
  // 因此按"当前页可见的行内徽标个数"来统计。注意：只覆盖当前页（默认 20 条/页），
  // 下降商品若在其它页则数不到——被动读数的固有限制，要精确总数得点筛选（主动模式）。
  function countDeclineBadges(all) {
    let n = 0;
    for (const e of all) {
      const t = (e.textContent || '').trim();
      if (!/商品流量近期有下降/.test(t) || t.length > 20) continue;
      // 只数最内层节点，避免父容器重复计数
      if ([...e.children].some((c) => /商品流量近期有下降/.test(c.textContent || ''))) continue;
      const r = e.getBoundingClientRect();
      if (r.width > 0 && r.height > 0) n++; // 只数真正渲染出来的行徽标，排除隐藏的筛选项/图例
    }
    return n;
  }
  // 扫描当前页商品行：按「SPU ID(=productId)」边界把行分组成商品，
  // 识别哪些商品带「商品流量待关注 / 商品流量近期有下降」徽标，取 productId + 商品名 + SKC。
  // 局限：只覆盖当前页(默认 20 条/页)，跨页的限流/下降商品扫不到——被动读的固有限制
  //（chip 计数 trafficWatch 才是全量总数；这里只为「点名 + 给编辑链接」）。
  function scanProducts() {
    const rows = [...document.querySelectorAll('[data-testid="beast-core-table-body-tr"]')];
    const products = [];
    let cur = null;
    for (const tr of rows) {
      const t = tr.textContent || '';
      const spu = t.match(/SPU\s*ID[:：]\s*(\d+)/); // DOM「SPU ID」= API/编辑页的 productId
      if (spu) {
        // 商品名只在「商品信息」那一格取（含 SPU ID 的 td），排除「标签：值」属性行，取最长一段。
        // （曾扫整行 → 第 3 条抓成隔壁「商品属性」列的「主体材质：铝合金」，故限定到该 td。）
        const infoTd = [...tr.querySelectorAll('td')].find((td) => /SPU\s*ID/.test(td.textContent || '')) || tr;
        const name = [...infoTd.querySelectorAll('*')].map((e) => (e.textContent || '').trim())
          .filter((x) => x.length >= 6 && x.length <= 80 && /[一-龥]/.test(x) && !/^.{0,6}[:：]/.test(x) && !/SPU|SKC/.test(x))
          .sort((a, b) => b.length - a.length)[0] || '';
        cur = { productId: spu[1], skc: (t.match(/SKC\s*ID[:：]\s*(\d+)/) || [])[1] || '', name: name, watch: false, decline: false };
        products.push(cur);
      }
      if (cur) {
        if (/商品流量待关注/.test(t)) cur.watch = true;
        if (/商品流量近期有下降/.test(t)) cur.decline = true;
      }
    }
    return products;
  }
  function readTraffic() {
    const all = [...document.querySelectorAll('*')];
    return {
      watch: readChipCount(all, '商品流量待关注'),
      decline: countDeclineBadges(all),
    };
  }
  const pickItem = (p) => ({ productId: p.productId, name: p.name, skc: p.skc });
  // 常驻轮询：每 2s 读一次 chip 计数 + 扫一次商品明细，但**只在结果变化时上报**
  //（靠 dedupe 避免刷爆后台）。这样用户后点「商品流量待关注」筛选/翻页时，
  // 明细也会在 2s 内自动刷新——旧版只在加载后 40s 内扫、之后点筛选就不扫了。
  let tries = 0;
  let lastKey = '';
  setInterval(() => {
    tries++;
    // 商品表格是否已渲染出行——徽标在行里，必须等行出来再扫，否则会在徽标出现前就读成空
    const gridReady = !!document.querySelector('[data-testid="beast-core-table-body-tr"]');
    const { watch, decline } = readTraffic();
    const msg = { type: 'chipStats', store: readStoreName() };
    if (watch != null) msg.trafficWatch = watch;
    let watchItems = [];
    let declineItems = [];
    if (gridReady) {
      const products = scanProducts();
      watchItems = products.filter((p) => p.watch).map(pickItem);
      declineItems = products.filter((p) => p.decline).map(pickItem);
      msg.trafficDecline = decline; // 仅在表格渲染后 decline 才可信
      msg.watchItems = watchItems;
      msg.declineItems = declineItems;
    }
    // 有 count 时等网格就绪再发（尽量带上明细）；网格长时间卡「加载中」(tries>8≈16s)时 count-only 兜底
    const readyOrTimedOut = gridReady || tries > 8;
    if (!((msg.trafficWatch != null && readyOrTimedOut) || 'trafficDecline' in msg)) return;
    // 结果没变化就不重发；变化了（如刚点了筛选、切了店）才上报
    const key = JSON.stringify([msg.store, msg.trafficWatch, msg.trafficDecline,
      watchItems.map((i) => i.productId), declineItems.map((i) => i.productId)]);
    if (key === lastKey) return;
    lastKey = key;
    try { chrome.runtime.sendMessage(msg); } catch (e) {}
  }, 2000);

  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
  async function waitFor(fn, timeout, step) {
    const t0 = Date.now();
    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
  }
  function textEls(re, maxLen) {
    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
  }
  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
  function realClick(el) {
    if (!el) return false;
    const opts = { bubbles: true, cancelable: true, view: window };
    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
    }
    try { el.click(); } catch (e) {}
    return true;
  }
  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
  function closeModal() {
    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
    if (x) { realClick(x); return; }
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
  }

  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
  function domSkel(el, maxLen) {
    if (!el) return 'null';
    let h = (el.outerHTML || '');
    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
    return h.slice(0, maxLen || 2200);
  }

  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }

  async function openStoreModal(diag) {
    diag = diag || [];
    if (modalOpen()) { diag.push('弹窗已开'); return true; }
    const nameEl = findStoreNameEl();
    diag.push('店名=' + (nameEl ? (nameEl.textContent || '').trim() : 'null'));
    if (nameEl) {
      // 只点一次触发下拉：点店名的可点祖先 + 店名右侧箭头坐标（避免多次点击把下拉又关掉）
      const r = nameEl.getBoundingClientRect();
      realClick(clickableAncestor(nameEl));
      const el = document.elementFromPoint(Math.min(window.innerWidth - 3, r.right + 14), r.top + r.height / 2);
      if (el && el !== nameEl) realClick(el);
    }
    // 下拉里“切换”按钮：只认可见的、精确文本“切换”，取最后一个（下拉通常在 DOM 靠后）
    const sw = await waitFor(() => {
      const cands = textEls(/^切换$/, 6).filter(visible);
      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
    }, 3500);
    diag.push('下拉切换按钮=' + !!sw);
    if (sw) realClick(sw);
    const ok = !!(await waitFor(() => (modalOpen() ? true : null), 4500));
    diag.push('弹窗打开=' + ok);
    if (!ok) {
      const cands = textEls(/切换/, 8).map((e) => {
        const b = e.getBoundingClientRect();
        return e.tagName + '.' + String(e.className || '').split(' ')[0] + '[' + (e.textContent || '').trim().slice(0, 6) + ',y' + Math.round(b.top) + ',w' + Math.round(b.width) + ']';
      });
      diag.push('切换候选(' + cands.length + ')=' + cands.join(' '));
      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
    }
    return ok;
  }

  async function listStores() {
    if (!(await openStoreModal())) return [];
    await sleep(500);
    // 每个店铺行都带“半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文
    const tags = textEls(/托管/, 6).filter(visible);
    const names = [];
    for (const tag of tags) {
      let row = tag.parentElement;
      for (let i = 0; i < 4 && row; i++) {
        const en = [...row.querySelectorAll('span,div,p,a')]
          .map((e) => (e.textContent || '').trim())
          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
        if (en) { names.push(en); break; }
        row = row.parentElement;
      }
    }
    closeModal();
    const uniq = [...new Set(names)];
    LOG('listStores =>', uniq);
    return uniq;
  }

  async function switchTo(target) {
    const diag = [];
    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
    await sleep(300);
    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
    const row = innermost(rows);
    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
    if (!btn) {
      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
    }
    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
    LOG('switchTo click', target);
    realClick(btn); // 触发切店（SPA 更新或整页重载）
    return { ok: true, msg: '已点击切换到 ' + target };
  }

  // ---------- 主动捞「商品流量待关注」明细（发现异常时调，点筛选→扫→重置） ----------
  // 读列表底部「共有 N 条」（筛选生效后该数=待关注总数）
  function readTotalCount() {
    const el = [...document.querySelectorAll('*')].find(
      (x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || '')
    );
    if (!el) return null;
    const m = (el.textContent || '').match(/共有\s*([\d,]+)\s*条/);
    return m ? Number(m[1].replace(/,/g, '')) : null;
  }
  // 定位「商品流量待关注」快速筛选 chip 容器（与 readChipCount 同一稳定 class 前缀）
  function findWatchChip() {
    for (const card of document.querySelectorAll('[class*="use-quick-field_tsx_card__"]')) {
      if (/商品流量待关注/.test(card.textContent || '')) return card;
    }
    return null;
  }
  // 点「重置」清掉快速筛选，恢复用户视图
  function clickReset() {
    const btn = textEls(/^重置$/, 6).filter(visible)[0];
    if (btn) realClick(clickableAncestor(btn));
  }
  // 点开「商品流量待关注」筛选 → 扫出这几条商品(productId+name+skc) → 重置。
  // 筛选生效后网格里每行都是待关注商品，故取全部行（不再依赖行内徽标）。
  // 只覆盖筛选后的当前页(默认 20 条)，>20 条的溢出由 total 提示行说明。
  async function scanWatchList() {
    const chip = findWatchChip();
    if (!chip) return { store: readStoreName(), items: [], applied: false, msg: '未找到待关注筛选 chip' };
    const before = readTotalCount();
    realClick(clickableAncestor(chip));
    // 等列表真正刷新：底部「共有 N 条」的数值发生变化（通常变小）才算筛选生效
    await waitFor(() => {
      const t = readTotalCount();
      return (t != null && before != null && t !== before) ? t : null;
    }, 8000, 300);
    await sleep(1200); // 等筛选后的网格稳定渲染
    const after = readTotalCount();
    // 仅当确实生效（数值变化且不大于原总数）才采纳，绝不把未筛选的整页当成待关注
    const applied = after != null && before != null && after !== before && after <= before;
    let items = [];
    if (applied) items = scanProducts().map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
    clickReset();
    await sleep(800);
    return { store: readStoreName(), items: items, total: after, applied: applied };
  }

  // 扫「在售中」商品清单：点在售 tab → 等在售网格 → scanProducts 取 productId+name+skc。
  // 用于 background diff 出"上轮在售、这轮不在"的下架商品。仅轮巡(空闲)时调，扫完点回「全部」。
  async function scanOnSaleList() {
    const findTab = (re) => {
      const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
      return labels.find((e) => re.test((e.textContent || '').trim())) || textEls(re, 14).filter(visible)[0] || null;
    };
    const onSaleTab = findTab(/^在售中/);
    if (onSaleTab) realClick(clickableAncestor(onSaleTab));
    await waitFor(() => document.querySelector('[data-testid="beast-core-table-body-tr"]'), 8000, 300);
    await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
    const products = scanProducts();
    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
    const allTab = findTab(/^全部/);
    if (allTab) realClick(clickableAncestor(allTab));
    return { store: readStoreName(), items: items };
  }

  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (!msg || !msg.cmd) return;
    (async () => {
      try {
        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; }
        if (msg.cmd === 'listStores') { sendResponse({ names: await listStores() }); return; }
        if (msg.cmd === 'switchTo') { sendResponse(await switchTo(msg.target)); return; }
        if (msg.cmd === 'scanOnSale') { sendResponse(await scanOnSaleList()); return; }
        if (msg.cmd === 'scanWatchList') { sendResponse(await scanWatchList()); return; }
      } catch (e) { sendResponse({ ok: false, msg: String((e && e.message) || e) }); }
    })();
    return true;
  });
})();

content.content:
1	// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
2	// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
3	// 数据只存本机 chrome.storage.local，不上传任何服务器。
4	
5	const GOODS_URL = 'https://agentseller.temu.com/goods/list';
6	const DEFAULT_CONFIG = { webhook: '', intervalMinutes: 15, enabled: true, storeName: '' };
7	
8	// ---------------- 解析 ----------------
9	function parseCountStatus(body) {
10	  try {
11	    const j = JSON.parse(body);
12	    const list = j && j.result && j.result.skcTopStatusCountList;
13	    if (!Array.isArray(list)) return null;
14	    const pick = (s) => {
15	      const x = list.find((e) => e && e.skcTopStatus === s);
16	      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
17	    };
18	    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
19	  } catch (e) { return null; }
20	}
21	function parsePageQuery(body) {
22	  try {
23	    const j = JSON.parse(body);
24	    const r = j && j.result;
25	    if (!r) return null;
26	    return { total: r.total };
27	  } catch (e) { return null; }
28	}
29	
30	// ---------------- 存取 ----------------
31	async function getConfig() {
32	  const { config } = await chrome.storage.local.get('config');
33	  return Object.assign({}, DEFAULT_CONFIG, config || {});
34	}
35	async function getStores() {
36	  const { stores } = await chrome.storage.local.get('stores');
37	  return stores || {};
38	}
39	async function saveStores(stores) {
40	  await chrome.storage.local.set({ stores });
41	}
42	// 更新某店的最新读数
43	async function updateStoreLatest(name, patch) {
44	  const stores = await getStores();
45	  const s = stores[name] || { latest: {}, snapshot: {} };
46	  s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
47	  stores[name] = s;
48	  await saveStores(stores);
49	  return s;
50	}
51	
52	// ---------------- 飞书 ----------------
53	async function sendFeishu(webhook, title, lines) {
54	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
55	  const card = {
56	    msg_type: 'interactive',
57	    card: {
58	      header: { title: { tag: 'plain_text', content: title }, template: 'red' },
59	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
60	    },
61	  };
62	  try {
63	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
64	    const data = await resp.json().catch(() => ({}));
65	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
66	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
67	  } catch (e) {
68	    return { ok: false, msg: '发送失败：' + (e && e.message) };
69	  }
70	}
71	
72	// ---------------- 商品明细 → 带链接的告警行 ----------------
73	// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
74	function editLink(productId) {
75	  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
76	}
77	// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
78	function itemLines(items, total) {
79	  const lines = [];
80	  if (Array.isArray(items) && items.length) {
81	    for (const it of items) {
82	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
83	      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
84	    }
85	    if (typeof total === 'number' && total > items.length) {
86	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
87	    }
88	  } else if (typeof total === 'number' && total > 0) {
89	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
90	  }
91	  return lines;
92	}
93	
94	// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
95	async function scanWatchViaTab() {
96	  const tab = await getGoodsTab();
97	  if (!tab) return null;
98	  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
99	}
100	
101	// ---------------- 对比 & 告警（按店） ----------------
102	// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
103	// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
104	const alertChains = {};
105	function diffAndAlert(name) {
106	  const prev = alertChains[name] || Promise.resolve();
107	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
108	  alertChains[name] = next;
109	  return next;
110	}
111	
112	async function _diffAndAlert(name) {
113	  const cfg = await getConfig();
114	  if (!cfg.enabled) return;
115	  const stores = await getStores();
116	  const s = stores[name];
117	  if (!s) return;
118	  const latest = s.latest || {};
119	  const snap = s.snapshot || {};
120	  const events = [];
121	
122	  // 在售下降不在这里报「只报数字」——改由 diffOnSale 按在售清单 diff 报「具体哪条下架」（带链接），避免同一事件报两次。
123	  if (typeof latest.trafficWatch === 'number' && typeof snap.trafficWatch === 'number' && latest.trafficWatch > snap.trafficWatch) {
124	    events.push(`⚠️ 商品流量待关注增加：${snap.trafficWatch} → ${latest.trafficWatch}`);
125	    // 被动扫到的 watchItems 往往为空（限流商品散落在其它页）→ 主动点筛选把这几条捞出来，带链接点名。
126	    let items = Array.isArray(latest.watchItems) ? latest.watchItems : [];
127	    let total = latest.trafficWatch;
128	    const scan = await scanWatchViaTab();
129	    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
130	      items = scan.items;
131	      if (typeof scan.total === 'number') total = scan.total;
132	    }
133	    events.push(...itemLines(items, total));
134	  }
135	  // 「商品流量近期有下降」商品数增加（相对已建立的基准，首次不报）
136	  if (typeof latest.trafficDecline === 'number' && typeof snap.trafficDecline === 'number' && latest.trafficDecline > snap.trafficDecline) {
137	    events.push(`🔴 商品流量近期有下降增加：${snap.trafficDecline} → ${latest.trafficDecline}（本页可见）`);
138	    events.push(...itemLines(latest.declineItems, null));
139	  }
140	
141	  if (events.length > 0) {
142	    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
143	    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
144	    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
145	  }
146	
147	  // 合并式更新该店基准快照（只覆盖本次拿到的数值），幂等只报一次。
148	  // 重新取一次 store：主动扫筛选期间 content 可能又上报过 latest，避免用旧闭包覆盖。
149	  const stores2 = await getStores();
150	  const s2 = stores2[name] || s;
151	  const L2 = s2.latest || latest;
152	  const newSnap = Object.assign({}, s2.snapshot || snap);
153	  if (typeof L2.onSale === 'number') newSnap.onSale = L2.onSale;
154	  if (typeof L2.total === 'number') newSnap.total = L2.total;
155	  if (typeof L2.trafficWatch === 'number') newSnap.trafficWatch = L2.trafficWatch;
156	  if (typeof L2.trafficDecline === 'number') newSnap.trafficDecline = L2.trafficDecline;
157	  newSnap.ts = Date.now();
158	  s2.snapshot = newSnap;
159	  stores2[name] = s2;
160	  await saveStores(stores2);
161	}
162	
163	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
164	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
165	async function diffOnSale(name, items) {
166	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
167	  const cfg = await getConfig();
168	  const stores = await getStores();
169	  const s = stores[name] || { latest: {}, snapshot: {} };
170	  // 防残缺扫描误判：已知在售数(countStatus)时，扫到的必须不少于它，否则视为没扫全 → 跳过
171	  const known = s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null;
172	  if (known != null && items.length < known) return 0;
173	  const newMap = {};
174	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
175	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
176	  let delistedCount = 0;
177	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
178	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
179	    delistedCount = delisted.length;
180	    if (delisted.length) {
181	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
182	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}）:`,
183	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
184	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
185	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
186	    }
187	  }
188	  s.snapshot = Object.assign({}, s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
189	  stores[name] = s;
190	  await saveStores(stores);
191	  return delistedCount;
192	}
193	
194	// 解析店铺名：优先用页面读到的店名；读不到则退回配置里手填的，再退回“当前店铺”
195	async function resolveStore(msgStore) {
196	  if (msgStore && String(msgStore).trim()) return String(msgStore).trim();
197	  const cfg = await getConfig();
198	  return (cfg.storeName && cfg.storeName.trim()) || '当前店铺';
199	}
200	
201	// ---------------- 消息处理 ----------------
202	chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
203	  (async () => {
204	    if (msg.type === 'capture') {
205	      const name = await resolveStore(msg.store);
206	      if (msg.kind === 'countStatus') {
207	        const p = parseCountStatus(msg.body);
208	        if (p && p.onSale != null) {
209	          await updateStoreLatest(name, { onSale: p.onSale, unpublished: p.unpublished, removed: p.removed, deleted: p.deleted });
210	          await diffAndAlert(name);
211	        }
212	      } else if (msg.kind === 'pageQuery') {
213	        const p = parsePageQuery(msg.body);
214	        if (p) await updateStoreLatest(name, { total: p.total });
215	      }
216	      sendResponse({ ok: true });
217	      return;
218	    }
219	    if (msg.type === 'chipStats') {
220	      const patch = {};
221	      if (typeof msg.trafficWatch === 'number') patch.trafficWatch = msg.trafficWatch;
222	      if (typeof msg.trafficDecline === 'number') patch.trafficDecline = msg.trafficDecline;
223	      if (Array.isArray(msg.watchItems)) patch.watchItems = msg.watchItems;
224	      if (Array.isArray(msg.declineItems)) patch.declineItems = msg.declineItems;
225	      if (Object.keys(patch).length) {
226	        const name = await resolveStore(msg.store);
227	        await updateStoreLatest(name, patch);
228	        await diffAndAlert(name);
229	      }
230	      sendResponse({ ok: true });
231	      return;
232	    }
233	    if (msg.type === 'getStatus') {
234	      sendResponse({ bgVersion: 'v4-限流点名', config: await getConfig(), stores: await getStores(), ...(await chrome.storage.local.get(['lastAlert', 'lastCycle'])) });
235	      return;
236	    }
237	    if (msg.type === 'addStore') {
238	      const name = (msg.name || '').trim();
239	      if (!name) { sendResponse({ ok: false, msg: '店铺名不能为空' }); return; }
240	      const stores = await getStores();
241	      if (stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」已存在' }); return; }
242	      stores[name] = { latest: {}, snapshot: {} };
243	      await saveStores(stores);
244	      sendResponse({ ok: true, msg: '已添加「' + name + '」，下次轮巡将尝试切到该店抓数' });
245	      return;
246	    }
247	    if (msg.type === 'deleteStore') {
248	      const name = (msg.name || '').trim();
249	      const stores = await getStores();
250	      if (!stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」不存在' }); return; }
251	      delete stores[name];
252	      await saveStores(stores);
253	      sendResponse({ ok: true, msg: '已删除「' + name + '」' });
254	      return;
255	    }
256	    if (msg.type === 'checkNow') {
257	      sendResponse(await pollNow());
258	      return;
259	    }
260	    if (msg.type === 'cycleNow') {
261	      sendResponse(await cycleStores('manual'));
262	      return;
263	    }
264	    if (msg.type === 'testFeishu') {
265	      const cfg = await getConfig();
266	      const r = await sendFeishu(cfg.webhook, '✅ Temu 监测测试', ['这是一条测试消息，收到说明飞书配置正常。', '', `_${new Date().toLocaleString('zh-CN')}_`]);
267	      sendResponse(r);
268	      return;
269	    }
270	  })();
271	  return true;
272	});
273	
274	// ---------------- 自动轮巡（切遍每个店抓数，再切回原店；仅空闲时触发） ----------------
275	const IDLE_SECONDS = 240; // 无操作 4 分钟视为空闲
276	let cycling = false;
277	
278	async function getGoodsTab() {
279	  const tabs = await chrome.tabs.query({ url: 'https://agentseller.temu.com/*' });
280	  return tabs.find((t) => /goods\/list/.test(t.url || '')) || tabs[0] || null;
281	}
282	function sendTab(tabId, cmd) {
283	  return new Promise((resolve) => {
284	    try {
285	      chrome.tabs.sendMessage(tabId, cmd, (resp) => {
286	        if (chrome.runtime.lastError) resolve(null); else resolve(resp);
287	      });
288	    } catch (e) { resolve(null); }
289	  });
290	}
291	async function sendTabRetry(tabId, cmd, tries) {
292	  for (let i = 0; i < (tries || 8); i++) {
293	    const r = await sendTab(tabId, cmd);
294	    if (r) return r;
295	    await new Promise((res) => setTimeout(res, 1000)); // 页面重载后 content 未就绪，重试
296	  }
297	  return null;
298	}
299	function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
300	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
301	async function waitForStoreCapture(name, sinceTs, timeout) {
302	  const t0 = Date.now();
303	  while (Date.now() - t0 < (timeout || 25000)) {
304	    const stores = await getStores();
305	    const L = stores[name] && stores[name].latest;
306	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
307	    await sleep(1500);
308	  }
309	  return false;
310	}
311	
312	async function cycleStores(reason) {
313	  if (cycling) return { ok: false, msg: '轮巡进行中' };
314	  cycling = true;
315	  const log = [];
316	  try {
317	    const tab = await getGoodsTab();
318	    if (!tab) return { ok: false, msg: '没有打开的 Temu 商品页' };
319	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
320	    const original = cur && cur.store;
321	    log.push('当前店：' + (original || '未知'));
322	
323	    // 店铺清单：优先用“已知店”（之前逛各店时按顶栏店名记下的，干净准确）；
324	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
325	    const known = Object.keys(await getStores()).filter((n) => n && n !== '当前店铺');
326	    let names;
327	    if (known.length >= 2) {
328	      names = known;
329	      log.push('店铺(已知)：' + names.join(', '));
330	    } else {
331	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
332	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
333	      log.push('店铺(探测)：' + names.join(', '));
334	    }
335	    if (names.length === 0) return { ok: false, msg: '没识别到店铺清单' };
336	
337	    for (const name of names) {
338	      if (name === original) continue; // 原店最后再确认；先切别的
339	      const since = Date.now();
340	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
341	      if (!r || !r.ok) { log.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
342	      const got = await waitForStoreCapture(name, since, 25000);
343	      log.push((got ? '✓ ' : '✗ ') + name);
344	      // 扫在售清单 → diff 出下架商品（带链接告警）
345	      if (got) {
346	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
347	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items); if (d) log.push('  ↳下架' + d + '个'); }
348	      }
349	    }
350	    // 切回原店
351	    if (original) {
352	      const since = Date.now();
353	      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
354	      const gotBack = await waitForStoreCapture(original, since, 25000);
355	      if (gotBack) {
356	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
357	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items); if (d) log.push('  ↳' + original + '下架' + d + '个'); }
358	      }
359	      log.push('已切回 ' + original);
360	    }
361	    const summary = log.join(' | ');
362	    await chrome.storage.local.set({ lastCycle: { ts: Date.now(), reason, summary } });
363	    return { ok: true, msg: summary };
364	  } finally { cycling = false; }
365	}
366	
367	async function pollNow() {
368	  const tab = await getGoodsTab();
369	  if (!tab) return { ok: false, msg: '未找到打开的 Temu 后台标签页，请先登录并打开商品列表页' };
370	  if (/goods\/list/.test(tab.url || '')) { await chrome.tabs.reload(tab.id, { bypassCache: false }); return { ok: true, msg: '已刷新后台商品页' }; }
371	  await chrome.tabs.update(tab.id, { url: GOODS_URL });
372	  return { ok: true, msg: '已导航到商品列表页' };
373	}
374	
375	// 定时：空闲则轮巡所有店，否则不打扰（靠随看随记覆盖当前店）
376	chrome.alarms.onAlarm.addListener((a) => {
377	  if (a.name !== 'poll') return;
378	  chrome.idle.queryState(IDLE_SECONDS, (state) => {
379	    if (state === 'idle' || state === 'locked') cycleStores('idle');
380	  });
381	});
382	
383	async function setupAlarm() {
384	  await chrome.storage.local.remove('trafficSample'); // 清早期诊断残留
385	  const cfg = await getConfig();
386	  await chrome.alarms.clear('poll');
387	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
388	}
