// 复刻 content.js 的 withLock，验证串行 + 结果/异常传播 + 错误不断链
let opChain = Promise.resolve();
function withLock(fn) {
  const run = opChain.then(fn, fn);
  opChain = run.then(() => {}, () => {});
  return run;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const events = [];
let fail = 0;
const check = (l, c) => { if (!c) { fail++; console.log('✗', l); } else console.log('✓', l); };

(async () => {
  // 并发发起三个任务：A(慢) B(会抛) C(快)，验证严格串行、互不重叠
  let active = 0, maxActive = 0;
  const task = (name, ms, throwIt) => async () => {
    active++; maxActive = Math.max(maxActive, active);
    events.push('start ' + name);
    await sleep(ms);
    events.push('end ' + name);
    active--;
    if (throwIt) throw new Error(name + ' boom');
    return name + '-result';
  };
  const pA = withLock(task('A', 40));
  const pB = withLock(task('B', 10, true));
